## Speculative Score Draft

const reverb = new Tone.Reverb({ decay: 8, wet: 0.5 }).toDestination();
const chorus = new Tone.Chorus(4, 2.5, 0.5).connect(reverb);

// Main Chords (PolySynth)
const chordSynth = new Tone.PolySynth(Tone.Synth, {
  oscillator: { type: 'fatsawtooth', count: 6, spread: 30 },
  envelope: { attack: 0.1, decay: 0.2, sustain: 1, release: 2 },
  filter: { type: 'lowpass', frequency: 5000, Q: 1.5 },
  volume: -9
}).connect(chorus);
const chordPart = new Tone.Part((time, note) => {
  chordSynth.triggerAttackRelease(note.notes, note.duration, time);
}, [
  { time: '0:0', notes: ['E3', 'G3', 'B3'], duration: '1m' },
  { time: '1:0', notes: ['C3', 'E3', 'G3'], duration: '1m' }
]).start(0);

// Arp Bass (MonoSynth)
const arpBass = new Tone.MonoSynth({
  oscillator: { type: 'sawtooth' },
  envelope: { attack: 0.01, decay: 0.2, sustain: 0.1, release: 0.1 },
  filter: { type: 'lowpass', frequency: 1200, Q: 4 },
  volume: -8
}).connect(reverb); // less chorus on bass
const arpPattern = new Tone.Pattern((time, note) => {
  arpBass.triggerAttackRelease(note, '16n', time);
}, ['E2', 'B2', 'E3', 'B2', 'E2', 'B2', 'E3', 'B2'], 'up');
arpPattern.interval = '16n';
arpPattern.start('4:0');

// Effects automation for risers would use Tone.Signal and .rampTo() on a filter's frequency.

/* SPECS / IDEAS FOR SCORE-DRAFTING */
// The track is built from two main bass parts, one rhythmic and one atmospheric.
// 1. Riff Bass: A Tone.MonoSynth with a 'fatsawtooth' oscillator (count: 4, spread: 20) for thickness. The envelope should be tight to articulate the fast notes (A:0.01, D:0.1, S:0.8, R:0.2). Use a lowpass filter around 450Hz with a Q of 2.5 for a focused, resonant sound, and add drive (~0.5) for grit. Sequence with a Tone.Sequence on a '16n' grid, e.g., ['E2', 'G2', 'B2', 'G2', 'D2', 'E2', 'C2', 'B1', ...]. This part carries the main energy.
// 2. Sub Drone: Another Tone.MonoSynth, this time with a 'triangle' oscillator for a purer low-end rumble. The key is the envelope: very slow attack (2.5s) and release (4.0s) to create swells. Filter it very low, around 180Hz, to keep it in sub territory. Add subtle drive (0.3) and reverb. Use Tone.Part to schedule single, long-duration notes like {time: '0:0', note: 'E1', duration: '4m'} to underpin the arrangement in intros and breakdowns.
